#!/bin/sh
set -eu
mkdir -p build/sim/obj-milestone5
# This intentionally uses the staged reference plus a separate HDL-board build.
docker run --rm --network none --platform linux/arm64 -v "$PWD:/work" -w /work --entrypoint sh jotego/simulator:arm64 -c 'verilator --cc --exe --build -j 4 --savable --assert -DNGAGE_RUNTIME_TRACE -DNGAGE_ASSOC_EXPERIMENT -DNGAGE_HDL_BOARD -CFLAGS "-DNGAGE_HDL_BOARD -I/work/tests/phone/reference/simif-board/board" -Wno-fatal -Wno-lint --x-initial 0 --x-assign 0 --top-module ngage_cpu_sim --Mdir build/sim/obj-milestone5 -Irtl/arm rtl/ngage_cpu.sv tests/phone/reference/milestone5/ngage_cpu_sim.sv rtl/arm/*.sv rtl/arm920/*.sv rtl/ngage_board.v rtl/ngage_upp.v rtl/ngage_upp_peripherals.v rtl/ngage_simif.v rtl/ngage_test_sim.v rtl/ngage_uem.v rtl/ngage_adsp.v rtl/ngage_lrb2.v rtl/ngage_mjoelner.v rtl/ngage_bram_be.v rtl/ngage_sparse_regs.v rtl/ngage_icu.v rtl/ngage_icu_extra.v rtl/ngage_timers.v rtl/ngage_nos_io.v rtl/ngage_mdi_stub.v rtl/ngage_cbus_uem.v rtl/ngage_gpio_loopback.v rtl/ngage_boot_regs.v rtl/ngage_trace_sink.v /work/tests/phone/reference/milestone5/main.cpp /work/tests/phone/reference/simif-board/board/boot_profile.cpp /work/tests/phone/reference/modem/ngage_modem.c' > build/sim/obj-milestone5/build.log 2>&1 || { tail -35 build/sim/obj-milestone5/build.log; exit 1; }
printf '%s\n' 'PASS built staged-reference HDL SIMIF simulator'
